import csv
import re
import io

data = """"Dyatlov Geçidi (Ölüm Dağı)","Ural Dağları","Rusya","1959'da 9 deneyimli dağcının çadırlarını içeriden yırtıp dondurucu soğuğa çıplak kaçarak feci şekilde can verdiği, Ural dağlarının kalbindeki o meşum zirve. Bölgenin yerlisi Mansilerin 'Ölüler Dağı' dediği bu alanda, gece çöktüğünde esen rüzgarın içinde o devasa, zihin büken radyasyon ve açıklanamayan yırtıcı bir boyutsal zeka hissedilir.",5"Khovrino (Hovrino) Terk Edilmiş Hastanesi","Moskova","Rusya","İnşaatı durdurulan ve yeraltı sularına gömülmeye başlayan, devasa bir 'Bio-Hazard' logosu şeklinde tasarlanmış bu dev beton iskelet. 90'larda Satanist tarikatların ('Nemostor') kanlı ayinler yaptığı ve sonrasında polis baskınıyla sulara gömüldüğü alt katlardan yükselen o ağır, şeytani frekans auranızı felç eder.",5"Myasnoy Bor (Ölüm Vadisi)","Novgorod","Rusya","İkinci Dünya Savaşı'nda on binlerce Sovyet ve Alman askerinin bataklıkta boğularak ve donarak can verdiği devasa ormanlık alan. Zamanın tamamen donduğu bu zifiri ormanda gezinirken, çamurdan yükselen savaş çığlıkları, barut kokusu ve arafta kalmış binlerce askerin yarattığı o ezici, devasa keder empatları bayıltır.",5"Lubyanka Hapishanesi (Eski KGB Karargahı)","Moskova","Rusya","Stalin'in 'Büyük Temizlik' döneminde yüz binlerce masumun işkenceden geçirilip bodrum katlarında ensesinden vurularak infaz edildiği bu kanlı istihbarat binası. Binanın yanından geçerken bile duvarlara mühürlenmiş olan o mutlak devlet terörü, çaresizlik ve taşlara sinmiş olan paslı kan frekansı nefesinizi keser.",5"Dargavs (Ölüler Şehri)","Kuzey Osetya","Rusya","Kafkas dağlarının sarp bir vadisine gizlenmiş, küçük taş kulübelerden oluşan ancak aslında binlerce veba kurbanının kemikleriyle dolu devasa bir nekropol. Vebalıların kendi rızalarıyla girip ölmeyi bekledikleri bu kulübelerin arasında dolaşırken, o derin boyun eğişin ve hastalığın sülfürik enerjisinin yarattığı boğucu sessizlik ruhunuzu ezer.",5"Mikhailovsky Şatosu (Mühendisler Kalesi)","St. Petersburg","Rusya","Suikast paranoyasıyla yaşayıp, kalenin inşası bittikten sadece 40 gün sonra kendi yatak odasında boğularak öldürülen Çar I. Pavel'in lanetli mekanı. Gece yarısı sarayın pencerelerinde parlayan bir mum ve pencerelerden size bakan Çar'ın o öfkeli, huzursuz hayaleti; ihanetin o soğuk ve aristokratik frekansını canlı tutar.",4"Kola Süper Derin Sondaj Deliği (Cehennemin Kapısı)","Murmansk","Rusya","Sovyetlerin yerin 12 kilometre altına inerek açtığı ve 1990'larda aniden mühürleyip terk ettiği, Kuzey Kutup dairesindeki bu paslı, izole çukur. Deliğin dibine indirilen mikrofonların insan çığlıklarına benzer sesler kaydettiği efsanesiyle bilinen bu alan; yeraltının o ağır, ezici cehennem frekansını yeryüzüne sızdırır.",5"Yusupov Sarayı (Moika Sarayı)","St. Petersburg","Rusya","Rus İmparatorluğu'nun karanlık mistiği Rasputin'in zehirlenip, kurşunlanıp, defalarca dövüldükten sonra nehre atılarak zar zor öldürülebildiği o kanlı mahzen. Rasputin'in o devasa, karanlık okült enerjisi sarayın alt katlarına adeta kazınmıştır; mahzene inenlerin hissettiği o fiziksel baskı ve ani bulantı, majikal bir kalıntıdır.",5"Peter ve Paul Kalesi (Trubetskoy Zindanı)","St. Petersburg","Rusya","Çarların siyasi düşmanlarını, hatta kendi çocuklarını (Deli Petro'nun oğlu Aleksey) hapsedip işkenceyle öldürttüğü bu buz gibi nehir adası kalesi. Neva nehrinin dondurucu suyu hücrelere sızarken, deliren ve donarak ölen mahkumların o saplantılı intikam enerjisi, kalenin taşlarında bir astral asit gibi kaynar.",4"Tunguska Patlama Alanı","Sibirya (Krasnoyarsk)","Rusya","1908'de Hiroşima'nın bin katı gücünde gizemli bir patlamayla milyonlarca ağacın kibrit çöpü gibi devrildiği bu uçsuz bucaksız tayga ormanı. Meteor mu, UFO mu yoksa Tesla deneyi mi olduğu asla çözülemeyen bu alanın merkezinde, pusulaları bozan, cihazları yakan ve insan zihnini aşırı yükleyen devasa bir manyetik/radyoaktif anomali yatar.",5"Butyrka Hapishanesi","Moskova","Rusya","Moskova'nın en eski ve en acımasız cezaevi olan, isyancıların ve Çarlık düşmanlarının zincirlere vurulduğu bu gotik zindan. Pugachev Kulesi'nde hapsedilen isyancıların feryatları ve duvarlardan süzülen o zifiri, klostrofobik keder frekansı; asırlar boyunca üst üste binen binlerce ölüm acısının yarattığı ağır bir portal oluşturur.",4"Şaman Kayası (Shamanka)","Olkhon Adası (Baykal Gölü)","Rusya","Dünyanın en derin gölünün ortasındaki bu devasa, sivri kaya oluşumu; Asya'nın en güçlü şamanik ibadet merkezlerinden (Tengricilik/Buryat şamanizmi) biridir. İnsanların girmesinin yasak olduğu bu kutsal mağaralardan yayılan o devasa, saf elementer ruh enerjisi, davul sesleriyle birleşerek insanı zorla astral boyuta çeker.",4"Kurşunlu Kilise Harabeleri (Vyborg)","Leningrad Oblastı","Rusya","Kış Savaşı sırasında Kızıl Ordu ile Fin birlikleri arasında el değiştiren ve ağır bombardımanla yıkılan bu eski katedral. Mezarların bile bombalarla parçalandığı bu harabelerde esen dondurucu Baltık rüzgarı; toprağından sökülen ölülerin o huzursuz ve agresif feryatlarını, arafta kalan savaşçıların fısıltılarına karıştırır.",4"Golosov Uçurumu (Zaman Kayması)","Moskova (Kolomenskoye)","Rusya","Moskova'nın ortasındaki bir parkta yer alan ama yeşil sislerin belirdiği ve girenlerin yıllar sonra yaşlanmadan geri döndüğü iddia edilen bu kadim Kelt (Slav pagan) yarığı. İki devasa 'kutsal' taşın (Kız Taşı ve Kaz Taşı) yarattığı o yoğun elektromanyetik girdap; uzay-zaman algısını büken aktif bir boyutsal solucan deliğidir.",5"Solyanka Yeraltı Dehlizleri (Tuz Mahzenleri)","Moskova","Rusya","Şehrin altında kilometrelerce uzanan, Çarlık döneminin tuz depoları ve sonrasının suç mafya tünelleri. Tamamen karanlığa ve suঁয় baskınlarına teslim olmuş bu klostrofobik labirentte ilerlerken, yeraltının o boğucu rutubet frekansıyla size doğru yaklaşan açıklanamaz ayak sesleri, saf bir panik atağı tetikler.",4"""

# Split by fixing the missing newline before a quote after a number
formatted_data = re.sub(r'(\d)"', r'\1\n"', data)

reader = csv.reader(io.StringIO(formatted_data))
with open('perili_mekanlar.csv', 'a', encoding='utf-8', newline='') as f:
    writer = csv.writer(f)
    for row in reader:
        # Avoid empty lines
        if not row:
            continue
        if len(row) == 5:
            row.append('') # resim_url
        writer.writerow(row)

print("Rusya kayitlari eklendi.")
